#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply_op=[&](int x,int y){
        vector<int> np;
        for(int i=n-y;i<n;i++) np.push_back(p[i]);
        for(int i=x;i<n-y;i++) np.push_back(p[i]);
        for(int i=0;i<x;i++) np.push_back(p[i]);
        p=np;
        ops.push_back({x,y});
    };
    for(int i=0;i<n-2;i++){
        int j=find(p.begin()+i,p.end(),i+1)-p.begin();
        if(j==i) continue;
        if(j==n-1){
            // Move it out of last position first: op(1,1) moves last to front
            if(n>2){apply_op(1,1);j=find(p.begin()+i,p.end(),i+1)-p.begin();}
            if(j==i) continue;
        }
        // Now j>i and j<n-1
        int x=j-i+1, y=1;
        if(x+y>=n){
            // j-i+2>=n, use op(1,n-1-j) if valid
            apply_op(1,n-1-j);
            j=find(p.begin()+i,p.end(),i+1)-p.begin();
            if(j==i) continue;
            x=j-i+1; y=1;
        }
        apply_op(x,y);
    }
    printf("%d\n",(int)ops.size());
    for(auto&[a,b]:ops) printf("%d %d\n",a,b);
}
